queries.typeql:
match
  $r isa reaction-like-event;
  compartment-assignment (localised-thing: $r, compartment: $c);
  $c isa compartment;
select $r, $c;
distinct;
reduce $total = count;
match
  $r isa reaction-like-event;
  compartment-assignment (localised-thing: $r, compartment: $c);
  $c isa compartment;
select $total, $r, $c;
distinct;
reduce $events = count($r) groupby $total, $c;
match
  $c has display-name $compartment;
  let $pct = round(100.0 * $events / $total * 10.0) / 10.0;
select $compartment, $events, $pct;
sort $events desc, $compartment asc;
limit 5;

match
  $r isa reaction-like-event;
  species-assignment (classified-thing: $r, species: $sp); $sp has display-name "Homo sapiens";
  compartment-assignment (localised-thing: $r, compartment: $c);
  $c isa compartment, has display-name "endoplasmic reticulum membrane";
select $r;
distinct;
reduce $target = count;
match
  $r isa reaction-like-event;
  species-assignment (classified-thing: $r, species: $sp); $sp has display-name "Homo sapiens";
  compartment-assignment (localised-thing: $r, compartment: $c);
  $c isa compartment;
select $target, $r, $c;
distinct;
reduce $n = count($r) groupby $target, $c;
match $n > $target;
select $c;
distinct;
reduce $above = count;
match let $rank = $above + 1;
select $rank;

match
  $r isa reaction-like-event;
  species-assignment (classified-thing: $r, species: $s);
select $s, $r;
distinct;
reduce $total = count($r) groupby $s;
sort $total desc;
limit 3;
match
  $r isa reaction-like-event;
  species-assignment (classified-thing: $r, species: $s);
  compartment-assignment (localised-thing: $r, compartment: $c);
  $c isa compartment;
select $s, $c;
distinct;
reduce $compartments = count($c) groupby $s;
match
  $r isa reaction-like-event;
  species-assignment (classified-thing: $r, species: $s);
  reaction-input (reaction: $r, consumed-entity: $i);
select $s, $compartments, $i;
distinct;
reduce $inputs = count($i) groupby $s, $compartments;
match
  $r isa reaction-like-event;
  species-assignment (classified-thing: $r, species: $s);
  catalysis (catalysed-reaction: $r, catalytic-activity: $f);
select $s, $compartments, $inputs, $f;
distinct;
reduce $functions = count($f) groupby $s, $compartments, $inputs;
match $s has display-name $species;
select $species, $compartments, $inputs, $functions;
sort $species asc;

match
  $r isa reaction-like-event;
  species-assignment (classified-thing: $r, species: $s);
select $s, $r;
distinct;
reduce $total = count($r) groupby $s;
sort $total desc;
limit 3;
match
  $p isa pathway;
  species-assignment (classified-thing: $p, species: $s);
  event-containment (containing-pathway: $p, contained-event: $e);
  $e isa reaction-like-event;
select $s, $p, $e;
distinct;
reduce $n = count($e) groupby $s, $p;
reduce $mean = mean($n) groupby $s;
match
  $p isa pathway;
  species-assignment (classified-thing: $p, species: $s);
  event-containment (containing-pathway: $p, contained-event: $e);
  $e isa reaction-like-event;
select $s, $mean, $p, $e;
distinct;
reduce $n = count($e) groupby $s, $mean, $p;
match
  $n > $mean;
  $s has display-name $species;
select $species, $p;
distinct;
reduce $pathways = count($p) groupby $species;
sort $species asc;

match
  $root isa pathway, has st-id "R-HSA-168256";
  event-containment (containing-pathway: $root, contained-event: $pp);
  $pp isa pathway;
  event-containment (containing-pathway: $pp, contained-event: $cc);
  $cc isa pathway;
  event-containment (containing-pathway: $cc, contained-event: $e);
  $e isa reaction-like-event;
select $pp, $cc, $e;
distinct;
reduce $reactions = count($e) groupby $pp, $cc;
match
  event-containment (containing-pathway: $pp, contained-event: $oo);
  $oo isa pathway;
  event-containment (containing-pathway: $oo, contained-event: $e2);
  $e2 isa reaction-like-event;
select $pp, $cc, $reactions, $oo, $e2;
distinct;
reduce $m = count($e2) groupby $pp, $cc, $reactions, $oo;
match
  $cc has display-name $cname;
  $oo has display-name $oname;
  { $m > $reactions; } or { $m == $reactions; $oname <= $cname; };
select $pp, $cc, $reactions, $oo;
distinct;
reduce $rank = count($oo) groupby $pp, $cc, $reactions;
match
  $rank <= 2;
  $pp has display-name $parent;
  $cc has display-name $child;
select $parent, $child, $reactions;
sort $parent asc, $reactions desc, $child asc;

match
  $r isa reaction-like-event;
  species-assignment (classified-thing: $r, species: $sp); $sp has display-name "Homo sapiens";
  reaction-input (reaction: $r, consumed-entity: $i);
select $r;
distinct;
reduce $total = count;
match
  $r isa reaction-like-event;
  species-assignment (classified-thing: $r, species: $sp); $sp has display-name "Homo sapiens";
  reaction-input (reaction: $r, consumed-entity: $i);
select $total, $r, $i;
distinct;
reduce $inputs = count($i) groupby $total, $r;
reduce $events = count($r) groupby $total, $inputs;
match let $pct = round(100.0 * $events / $total * 10.0) / 10.0;
select $inputs, $events, $pct;
sort $events desc, $inputs asc;
limit 5;

match
  $p isa pathway;
  species-assignment (classified-thing: $p, species: $sp); $sp has display-name "Homo sapiens";
  event-containment (containing-pathway: $p, contained-event: $e);
  $e isa reaction-like-event;
select $p, $e;
distinct;
reduce $events = count($e) groupby $p;
match
  $events >= 20;
  event-containment (containing-pathway: $p, contained-event: $e2);
  $e2 isa reaction-like-event;
  reaction-input (reaction: $e2, consumed-entity: $i);
select $p, $events, $i;
distinct;
reduce $inputs = count($i) groupby $p, $events;
match let $ratio = 1.0 * $inputs / $events;
select $p, $ratio;
sort $ratio desc;
limit 1;
match $p has display-name $name;
select $name;

match
  $p isa pathway;
  species-assignment (classified-thing: $p, species: $sp);
  $sp has display-name "Homo sapiens";
  curation (curated-object: $p, edit: $ie);
  edit-authorship (authored-edit: $ie, edit-author: $person);
  person-affiliation (affiliated-person: $person, affiliation: $af);
  $af has affiliation-name $an;
  $an contains "University";
select $p;
distinct;
reduce $count = count;

match
  composition (whole: $w, part: $x);
select $x, $w;
distinct;
reduce $n = count($w) groupby $x;
match $n >= 3;
reduce $count = count;

match
  reaction-participation (reaction: $r, participant: $x);
  species-assignment (classified-thing: $r, species: $sp);
  $sp has display-name "Homo sapiens";
select $x, $r;
distinct;
reduce $n = count($r) groupby $x;
match $n > 100;
reduce $count = count;

match
  $np isa negative-precedence, links (excluded-preceding-event: $a, following-event: $b);
  not { $np links (exclusion-reason: $why); };
select $a, $b;
distinct;
reduce $count = count;

match
  $r isa reaction-like-event;
  species-assignment (classified-thing: $r, species: $sp);
  $sp has display-name "Homo sapiens";
  entity-functional-status (affected-event: $r, disease-entity: $de, normal-entity: $ne);
  $de isa complex;
  $ne isa complex;
  not { composition (whole: $de, part: $x); composition (whole: $ne, part: $x); };
select $de, $ne;
distinct;
reduce $count = count;

match
  $t sub! physical-entity;
  $st sub $t;
  $x isa $st;
  reaction-input (reaction: $r, consumed-entity: $x);
  species-assignment (classified-thing: $r, species: $sp);
  $sp has display-name "Homo sapiens";
select $t;
distinct;
reduce $count = count;

match
  $p isa pathway;
  species-assignment (classified-thing: $p, species: $sp);
  $sp has display-name "Homo sapiens";
  $c isa $ct, links (curated-object: $p, edit: $ie);
  $ct sub! curation;
select $p, $ct;
distinct;
reduce $n = count($ct) groupby $p;
match $n >= 5;
reduce $count = count;

match
  $x has name $n;
  $n contains "PIK3";
  not { $x has display-name $d; $d contains "PIK3"; };
select $x;
distinct;
reduce $count = count;

match
  $h isa physical-entity, has entity-name $n;
  species-assignment (classified-thing: $h, species: $hs);
  $hs has display-name "Homo sapiens";
  $b isa physical-entity, has entity-name $n;
  species-assignment (classified-thing: $b, species: $bt);
  $bt has display-name "Bos taurus";
select $n;
distinct;
reduce $count = count;

match
  $p isa physical-entity, has entity-name $n;
  species-assignment (classified-thing: $p, species: $sp);
  $sp has display-name "Homo sapiens";
  $r isa reference-entity, has entity-name $n;
  not { reference-assignment (instance-entity: $p, reference: $r); };
select $p;
distinct;
reduce $count = count;

match
  $n isa name;
  $n contains "ras";
  $n isa! $t;
select $t;
distinct;
reduce $count = count;
